// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 first, uint256 second, address actor) public {
        vm.assume(first <= VALUE_CAP);
        vm.assume(second <= VALUE_CAP);
        vm.assume(actor != address(0));
        first = bound(first, 1, type(uint128).max);
        second = bound(second, 1, type(uint128).max);
        vm.deal(actor, first + second);
        vm.prank(actor); c.addToBalance{value: first}();
        vm.prank(actor); c.addToBalance{value: second}();
        assertEq(c.getBalance(actor), first + second);
    }
}
